/**
 * PHP ↔ JS parity: every case in tests/fixtures/styles.json (generated by
 * `composer fixtures` from the real PHP classes) must sanitize to the same
 * values and compile to the exact same CSS in JS.
 */
import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';

import { describe, expect, test } from 'vitest';

import { breakpointListFromJson } from '../src/Breakpoints/breakpoints';
import { BlockStyles } from '../src/Blocks/Values/block-styles';
import { StatefulValues } from '../src/Blocks/Values/stateful-values';
import { blockDefinitionFromJson } from '../src/Blocks/Definition/block-definition';
import { JsonValue } from '../src/Json/json';
import { CssLayer, Selector } from '../src/Styles/css';
import { StyleCompiler } from '../src/Styles/compiler';
import { formatCssNumber } from '../src/Values/css-number';
import { Preset, Presets } from '../src/Presets/presets';

const fixtures = JsonValue.of(
	JSON.parse( readFileSync( fileURLToPath( new URL( './Fixtures/styles.json', import.meta.url ) ), 'utf8' ) ) as unknown,
	'styles.json'
);

const breakpoints = breakpointListFromJson( fixtures.get( 'breakpoints' ) );
const presets = new Presets( fixtures.get( 'presets' ).list().map( Preset.fromJson ) );
const compiler = new StyleCompiler( breakpoints, presets );
const styles = new BlockStyles( breakpoints );

class ParityCase {
	constructor(
		public readonly name: string,
		private readonly json: JsonValue
	) {}

	run(): void {
		const definition = blockDefinitionFromJson( this.json.get( 'definition' ) );
		const values = StatefulValues.fromJson( this.json.get( 'attribute' ).decoded(), definition, breakpoints );
		const defaults = StatefulValues.fromJson( this.json.get( 'defaults' ).decoded(), definition, breakpoints );
		const root = Selector.forClass( this.json.get( 'rootClass' ).string() );

		// Compare values, not encodings (PHP writes 10.0, JS writes 10).
		expect( JSON.parse( JSON.stringify( values ) ) ).toEqual( this.json.get( 'values' ).decoded() );
		expect( styles.forSource( definition, defaults, Selector.forClass( definition.className ) ).css( compiler, CssLayer.Defaults ) ).toBe(
			this.json.get( 'defaultsCss' ).string()
		);
		expect( styles.forSource( definition, values, root, defaults ).css( compiler, CssLayer.Instances ) ).toBe( this.json.get( 'css' ).string() );
	}
}

const cases = fixtures
	.get( 'cases' )
	.list()
	.map( ( json ) => new ParityCase( json.get( 'name' ).string(), json ) );

describe( 'PHP ↔ JS parity', () => {
	test( 'fixtures are present', () => {
		expect( cases.length ).toBeGreaterThan( 5 );
	} );

	test.each( cases.map( ( parityCase ) => [ parityCase.name, parityCase ] as const ) )( '%s', ( _name, parityCase ) => {
		parityCase.run();
	} );
} );

describe( 'formatCssNumber matches PHP CssNumber::format', () => {
	test.each( [
		[ 16, '16' ],
		[ 1.5, '1.5' ],
		[ -12.25, '-12.25' ],
		[ 0.00001, '0' ],
		[ -0, '0' ],
		[ 0.0001, '0.0001' ],
		[ 33.33333, '33.3333' ],
	] )( '%p → %p', ( input, expected ) => {
		expect( formatCssNumber( input ) ).toBe( expected );
	} );
} );
